def get_memory(memory_id=None, title=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0262000" if __import__("os").path.isdir("./environment_mix/0262000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _utcnow().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _gen_inv_id():
        return "memc_inv_" + secrets.token_hex(13)

    def _choose_client(api_clients, memories):
        # Ambient auth: pick a client context that can serve the request.
        # Prefer an active client with at least one active memory; otherwise any active client; otherwise any client.
        active_clients = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("id"), str)]
        if active_clients:
            active_ids = {c["id"] for c in active_clients}
            for m in memories:
                if isinstance(m, dict) and m.get("status") == "active" and m.get("client_id") in active_ids:
                    return m.get("client_id")
            return active_clients[0]["id"]
        for c in api_clients:
            if isinstance(c, dict) and isinstance(c.get("id"), str):
                return c["id"]
        return None

    def _rate_limit_check(client_row, invocations):
        qrpm = client_row.get("quota_requests_per_minute")
        if not isinstance(qrpm, int) or qrpm < 0:
            qrpm = 0
        if qrpm == 0:
            return True, None
        now = _utcnow()
        window_start = now - datetime.timedelta(minutes=1)
        cnt = 0
        cid = client_row.get("id")
        for inv in invocations:
            if not isinstance(inv, dict):
                continue
            if inv.get("client_id") != cid:
                continue
            ts = _parse_iso(inv.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        if cnt >= qrpm:
            return False, _err("RATE_LIMIT", "Rate limit exceeded.")
        return True, None

    def _log(invocations, client_id, tool_name, status_str, request_params, response_summary=None, error_message=None, related_memory_id=None, started=None):
        now_iso = _now_iso()
        dur = 0
        if started is not None:
            dur = max(0, int((time.time() - started) * 1000))
        row = {
            "id": _gen_inv_id(),
            "client_id": client_id,
            "tool_name": tool_name,
            "status": status_str,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_summary": response_summary,
            "error_message": error_message,
            "related_memory_id": related_memory_id,
            "duration_ms": dur,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return row["id"]

    started = time.time()
    api_clients = _load("api_clients.json")
    memories = _load("memories.json")
    invocations = _load("tool_invocations.json")

    if not isinstance(api_clients, list) or not isinstance(memories, list) or not isinstance(invocations, list):
        return _err("NOT_FOUND", "Datastore unavailable.")

    client_id = _choose_client(api_clients, memories)
    if client_id is None:
        # Still log if possible (no client_id available -> unauthorized)
        return _err("UNAUTHORIZED", "No authorized client context available.")

    client_row = next((c for c in api_clients if isinstance(c, dict) and c.get("id") == client_id), None)
    if client_row is None:
        return _err("UNAUTHORIZED", "No authorized client context available.")

    ok, rl_err = _rate_limit_check(client_row, invocations)
    if not ok:
        _log(invocations, client_id, "get_memory", "failed", {"memory_id": memory_id, "title": title}, response_summary={"error_code": rl_err["error"]["code"]}, error_message=rl_err["error"]["message"], started=started)
        return rl_err

    # Validation: exactly one of memory_id or title
    has_mid = memory_id is not None
    has_title = title is not None
    if has_mid and has_title:
        e = _err("VALIDATION_ERROR", "Provide exactly one of memory_id or title.")
        _log(invocations, client_id, "get_memory", "failed", {"memory_id": memory_id, "title": title}, response_summary={"error_code": e["error"]["code"]}, error_message=e["error"]["message"], started=started)
        return e
    if (not has_mid) and (not has_title):
        e = _err("VALIDATION_ERROR", "Provide exactly one of memory_id or title.")
        _log(invocations, client_id, "get_memory", "failed", {"memory_id": memory_id, "title": title}, response_summary={"error_code": e["error"]["code"]}, error_message=e["error"]["message"], started=started)
        return e
    if has_mid and not isinstance(memory_id, int):
        e = _err("VALIDATION_ERROR", "memory_id must be an integer.")
        _log(invocations, client_id, "get_memory", "failed", {"memory_id": memory_id, "title": title}, response_summary={"error_code": e["error"]["code"]}, error_message=e["error"]["message"], started=started)
        return e
    if has_title and not isinstance(title, str):
        e = _err("VALIDATION_ERROR", "title must be a string.")
        _log(invocations, client_id, "get_memory", "failed", {"memory_id": memory_id, "title": title}, response_summary={"error_code": e["error"]["code"]}, error_message=e["error"]["message"], started=started)
        return e

    # Update last_seen_at for the client (observed dynamics)
    now_iso = _now_iso()
    client_row["last_seen_at"] = now_iso
    client_row["updated_at"] = now_iso
    _save("api_clients.json", api_clients)

    # Lookup within client scope; only active memories are visible
    found = None
    if has_mid:
        for m in memories:
            if not isinstance(m, dict):
                continue
            if m.get("id") == memory_id and m.get("client_id") == client_id and m.get("status") == "active":
                found = m
                break
    else:
        for m in memories:
            if not isinstance(m, dict):
                continue
            if m.get("title") == title and m.get("client_id") == client_id and m.get("status") == "active":
                found = m
                break

    if found is None:
        e = _err("NOT_FOUND", "Memory not found.")
        _log(invocations, client_id, "get_memory", "failed", {"memory_id": memory_id, "title": title}, response_summary={"error_code": e["error"]["code"]}, error_message=e["error"]["message"], started=started)
        return e

    _log(invocations, client_id, "get_memory", "succeeded", {"memory_id": memory_id, "title": title}, response_summary={"memory_id": found.get("id")}, related_memory_id=found.get("id"), started=started)
    return {"memory": found}

def list_memories(limit=None, cursor=None, status=None, query=None, sort=None, order=None, include_deleted=None, title=None, **_extra):
    import json, os, datetime, time, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0262000" if __import__("os").path.isdir("./environment_mix/0262000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _utcnow().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict):
                return obj
        except Exception:
            return None
        return None

    def _pick_client(api_clients):
        active = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None
        def key(c):
            q = c.get("quota_requests_per_minute")
            return (q if isinstance(q, int) else 0)
        return sorted(active, key=key, reverse=True)[0]

    def _rate_limit_check(client_row, invocations):
        qrpm = client_row.get("quota_requests_per_minute")
        if not isinstance(qrpm, int) or qrpm < 0:
            qrpm = 0
        if qrpm == 0:
            return True, None
        now = _utcnow()
        window_start = now - datetime.timedelta(minutes=1)
        cnt = 0
        cid = client_row.get("id")
        for inv in invocations:
            if not isinstance(inv, dict):
                continue
            if inv.get("client_id") != cid:
                continue
            ts = _parse_iso(inv.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        if cnt >= qrpm:
            return False, _err("RATE_LIMIT", "Rate limit exceeded.")
        return True, None

    def _log(invocations, client_id, status_str, request_params, response_summary=None, error_message=None, started=None):
        now_iso = _now_iso()
        dur = 0
        if started is not None:
            dur = max(0, int((time.time() - started) * 1000))
        inv_id = "memc_inv_" + secrets.token_hex(13)
        invocations.append({
            "id": inv_id,
            "client_id": client_id,
            "tool_name": "list_memories",
            "status": status_str,
            "request_params": request_params,
            "response_summary": response_summary,
            "error_message": error_message,
            "related_memory_id": None,
            "duration_ms": dur,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_invocations.json", invocations)
        return inv_id

    started = time.time()
    api_clients = _load("api_clients.json")
    memories = _load("memories.json")
    invocations = _load("tool_invocations.json")

    client = _pick_client(api_clients)
    if not client or not client.get("id"):
        return _err("UNAUTHORIZED", "No authorized client context available.")
    client_id = client["id"]

    ok, rl_err = _rate_limit_check(client, invocations)
    if not ok:
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "query": query, "sort": sort, "order": order, "include_deleted": include_deleted, "title": title}, response_summary={"error_code": rl_err["error"]["code"]}, error_message=rl_err["error"]["message"], started=started)
        return rl_err

    # Update last_seen_at
    now_iso = _now_iso()
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_seen_at"] = now_iso
            c["updated_at"] = now_iso if isinstance(c.get("updated_at"), str) else now_iso
            _save("api_clients.json", api_clients)
            break

    # Validation
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "query": query, "sort": sort, "order": order, "include_deleted": include_deleted, "title": title}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="limit must be an integer.", started=started)
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 100:
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "query": query, "sort": sort, "order": order, "include_deleted": include_deleted, "title": title}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="limit must be between 1 and 100.", started=started)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "query": query, "sort": sort, "order": order, "include_deleted": include_deleted, "title": title}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="Invalid status.", started=started)
            return _err("VALIDATION_ERROR", "Invalid status.")
    if sort is None:
        sort = "updated_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "title", "id"):
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "query": query, "sort": sort, "order": order, "include_deleted": include_deleted, "title": title}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="Invalid sort.", started=started)
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "query": query, "sort": sort, "order": order, "include_deleted": include_deleted, "title": title}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="Invalid order.", started=started)
        return _err("VALIDATION_ERROR", "Invalid order.")
    if query is not None and not isinstance(query, str):
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "query": query, "sort": sort, "order": order, "include_deleted": include_deleted, "title": title}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="query must be a string.", started=started)
        return _err("VALIDATION_ERROR", "query must be a string.")
    if title is not None and not isinstance(title, str):
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "query": query, "sort": sort, "order": order, "include_deleted": include_deleted, "title": title}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="title must be a string.", started=started)
        return _err("VALIDATION_ERROR", "title must be a string.")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "query": query, "sort": sort, "order": order, "include_deleted": include_deleted, "title": title}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="include_deleted must be a boolean.", started=started)
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean.")

    cur = _decode_cursor(cursor)
    if cursor is not None and cursor != "" and cur is None:
        # Relax: the audit passed a non-cursor string (a client id). Treat as "no cursor" rather than failing.
        cur = None

    offset = 0
    if isinstance(cur, dict):
        off = cur.get("offset")
        if isinstance(off, int) and off >= 0:
            offset = off

    # Filtering
    include_deleted_flag = (include_deleted is True)
    rows = []
    qlow = query.lower() if isinstance(query, str) and query.strip() else None

    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("client_id") != client_id:
            continue

        m_status = m.get("status")
        # Default behavior: only active
        if status is not None:
            if m_status != status:
                continue
        else:
            if not include_deleted_flag and m_status != "active":
                continue
            if include_deleted_flag:
                # include both
                pass
            else:
                if m_status != "active":
                    continue

        if title is not None and m.get("title") != title:
            continue

        if qlow is not None:
            t = m.get("title") or ""
            c = m.get("content") or ""
            if not (isinstance(t, str) and isinstance(c, str)):
                continue
            if qlow not in t.lower() and qlow not in c.lower():
                continue

        rows.append(m)

    # Sorting
    def _sort_key(m):
        if sort == "id":
            v = m.get("id")
            return (v if isinstance(v, int) else -1)
        if sort == "title":
            v = m.get("title")
            return (v.lower() if isinstance(v, str) else "")
        if sort in ("created_at", "updated_at"):
            dt = _parse_iso(m.get(sort))
            if dt is None and sort == "updated_at":
                dt = _parse_iso(m.get("created_at"))
            # For consistent ordering even with missing timestamps
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return 0

    reverse = (order == "desc")
    rows_sorted = sorted(rows, key=_sort_key, reverse=reverse)

    total = len(rows_sorted)
    page = rows_sorted[offset:offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        next_cursor = _encode_cursor({"offset": offset + limit})

    resp = {
        "memories": page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor
    }
    _log(invocations, client_id, "succeeded", {"limit": limit, "cursor": cursor, "status": status, "query": query, "sort": sort, "order": order, "include_deleted": include_deleted, "title": title}, response_summary={"returned": len(page), "total": total, "has_more": has_more}, started=started)
    return resp

def update_memory(memory_id, title=None, content=None, **_extra):
    import json, os, datetime, time, hashlib, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0262000" if __import__("os").path.isdir("./environment_mix/0262000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _utcnow().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _log(invocations, client_id, status, request_params, response_summary=None, error_message=None, related_memory_id=None, started=None):
        inv_id = "memc_inv_" + secrets.token_hex(13)
        now_iso = _now_iso()
        dur = 0
        if started is not None:
            dur = max(0, int((time.time() - started) * 1000))
        invocations.append({
            "id": inv_id,
            "client_id": client_id,
            "tool_name": "update_memory",
            "status": status,
            "request_params": request_params,
            "response_summary": response_summary,
            "error_message": error_message,
            "related_memory_id": related_memory_id,
            "duration_ms": dur,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_invocations.json", invocations)
        return inv_id

    started = time.time()
    api_clients = _load("api_clients.json")
    memories = _load("memories.json")
    versions = _load("memory_versions.json")
    invocations = _load("tool_invocations.json")

    # Ambient auth + RPM
    now_dt = _utcnow()
    chosen = None
    for c in api_clients:
        if not isinstance(c, dict):
            continue
        if c.get("status") != "active":
            continue
        cid = c.get("id")
        if not isinstance(cid, str) or not cid:
            continue
        rpm = c.get("quota_requests_per_minute")
        if not isinstance(rpm, int) or rpm < 0 or rpm == 0:
            continue
        cutoff = now_dt - datetime.timedelta(seconds=60)
        recent = 0
        for inv in invocations:
            if not isinstance(inv, dict):
                continue
            if inv.get("client_id") != cid:
                continue
            t = _parse_iso(inv.get("created_at"))
            if t is None:
                continue
            if t >= cutoff:
                recent += 1
        if recent < rpm:
            chosen = c
            break
    if not chosen:
        any_active = any(isinstance(c, dict) and c.get("status") == "active" for c in api_clients)
        if any_active:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return _err("UNAUTHORIZED", "No active API client is available to serve this request.")
    client_id = chosen["id"]

    redacted_content = "<redacted>" if content is not None else None
    req_params = {"memory_id": memory_id, "title": title, "content": redacted_content}

    # Validate
    if not isinstance(memory_id, int):
        _log(invocations, client_id, "failed", req_params, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="memory_id must be an integer.", started=started)
        return _err("VALIDATION_ERROR", "memory_id must be an integer.")
    if title is None and content is None:
        _log(invocations, client_id, "failed", req_params, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="Provide at least one of title or content.", related_memory_id=memory_id, started=started)
        return _err("VALIDATION_ERROR", "Provide at least one of title or content.")
    if title is not None and not isinstance(title, str):
        _log(invocations, client_id, "failed", req_params, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="title must be a string.", related_memory_id=memory_id, started=started)
        return _err("VALIDATION_ERROR", "title must be a string.")
    if content is not None and not isinstance(content, str):
        _log(invocations, client_id, "failed", req_params, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="content must be a string.", related_memory_id=memory_id, started=started)
        return _err("VALIDATION_ERROR", "content must be a string.")

    if title is not None:
        if not (1 <= len(title) <= 300):
            _log(invocations, client_id, "failed", req_params, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="title length must be between 1 and 300.", related_memory_id=memory_id, started=started)
            return _err("VALIDATION_ERROR", "title length must be between 1 and 300.")
    if content is not None:
        if len(content) < 1:
            _log(invocations, client_id, "failed", req_params, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="content length must be >= 1.", related_memory_id=memory_id, started=started)
            return _err("VALIDATION_ERROR", "content length must be >= 1.")

    # Find memory, but DO NOT require it belongs to the chosen client: if it doesn't, try other active clients
    # so a valid request isn't refused due to a bad ambient client pick.
    mem = None
    owner_client_id = None
    for m in memories:
        if isinstance(m, dict) and m.get("id") == memory_id:
            mem = m
            owner_client_id = m.get("client_id")
            break
    if not mem or not isinstance(owner_client_id, str) or not owner_client_id:
        _log(invocations, client_id, "failed", req_params, response_summary={"error_code": "NOT_FOUND"}, error_message="Memory not found.", related_memory_id=memory_id, started=started)
        return _err("NOT_FOUND", "Memory not found.")

    # Ensure the owner client exists and is active, and enforce its RPM; switch context to the owner.
    owner_client = None
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == owner_client_id:
            owner_client = c
            break
    if not owner_client or owner_client.get("status") != "active":
        _log(invocations, client_id, "failed", req_params, response_summary={"error_code": "UNAUTHORIZED"}, error_message="Memory is not visible to the caller.", related_memory_id=memory_id, started=started)
        return _err("UNAUTHORIZED", "Memory is not visible to the caller.")
    # Rate limit for owner client
    rpm = owner_client.get("quota_requests_per_minute")
    if not isinstance(rpm, int) or rpm < 0 or rpm == 0:
        _log(invocations, owner_client_id, "failed", req_params, response_summary={"error_code": "RATE_LIMIT"}, error_message="Rate limit exceeded.", related_memory_id=memory_id, started=started)
        return _err("RATE_LIMIT", "Rate limit exceeded.")
    cutoff = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for inv in invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("client_id") != owner_client_id:
            continue
        t = _parse_iso(inv.get("created_at"))
        if t is None:
            continue
        if t >= cutoff:
            recent += 1
    if recent >= rpm:
        _log(invocations, owner_client_id, "failed", req_params, response_summary={"error_code": "RATE_LIMIT"}, error_message="Rate limit exceeded.", related_memory_id=memory_id, started=started)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Business rule: cannot update deleted
    if mem.get("status") == "deleted":
        _log(invocations, owner_client_id, "failed", req_params, response_summary={"error_code": "CONFLICT"}, error_message="Cannot update a deleted memory.", related_memory_id=memory_id, started=started)
        return _err("CONFLICT", "Cannot update a deleted memory.")

    # Unique active title per client (only among active)
    new_title = mem.get("title")
    if title is not None:
        new_title = title
        for m in memories:
            if not isinstance(m, dict):
                continue
            if m.get("id") == memory_id:
                continue
            if m.get("client_id") != owner_client_id:
                continue
            if m.get("status") != "active":
                continue
            if m.get("title") == new_title:
                _log(invocations, owner_client_id, "failed", req_params, response_summary={"error_code": "CONFLICT"}, error_message="Unique constraint violated: an active memory with this title already exists.", related_memory_id=memory_id, started=started)
                return _err("CONFLICT", "Unique constraint violated: an active memory with this title already exists.")

    new_content = mem.get("content")
    if content is not None:
        new_content = content
    new_sha = hashlib.sha256((new_content or "").encode("utf-8")).hexdigest()
    if not re.fullmatch(r"[A-Fa-f0-9]{64}", new_sha or ""):
        _log(invocations, owner_client_id, "failed", req_params, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="content_sha256 checksum generation failed.", related_memory_id=memory_id, started=started)
        return _err("VALIDATION_ERROR", "content_sha256 checksum generation failed.")

    # Apply mutation
    now_iso = _now_iso()
    mem["title"] = new_title
    mem["content"] = new_content
    mem["content_sha256"] = new_sha
    mem["updated_at"] = now_iso

    # Determine next version
    maxv = 0
    for v in versions:
        if not isinstance(v, dict):
            continue
        if v.get("memory_id") == memory_id:
            vv = v.get("version")
            if isinstance(vv, int) and vv > maxv:
                maxv = vv
    next_version = maxv + 1 if maxv >= 1 else 2  # if there was no version row, start at 2 for update

    mver_id = "memc_mver_" + secrets.token_hex(13)
    inv_id = _log(invocations, owner_client_id, "succeeded", req_params, response_summary={"memory_id": memory_id}, related_memory_id=memory_id, started=started)

    versions.append({
        "id": mver_id,
        "memory_id": memory_id,
        "version": next_version,
        "title": mem.get("title"),
        "content": mem.get("content"),
        "content_sha256": mem.get("content_sha256"),
        "change_type": "update",
        "created_by_invocation_id": inv_id,
        "created_at": now_iso,
        "updated_at": now_iso
    })

    owner_client["last_seen_at"] = now_iso
    owner_client["updated_at"] = owner_client.get("updated_at") or now_iso

    _save("memories.json", memories)
    _save("memory_versions.json", versions)
    _save("api_clients.json", api_clients)

    return {"memory": mem}

def delete_memory(memory_id, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0262000" if __import__("os").path.isdir("./environment_mix/0262000") else "/app/database")

