        if any_active:
            _log(invocations, any_active["id"], "failed", {"memory_id": memory_id}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="memory_id must be an integer.", related_memory_id=None, started=started)
        return _err("VALIDATION_ERROR", "memory_id must be an integer.")

    # Find memory
    mem = None
    for m in memories:
        if isinstance(m, dict) and m.get("id") == memory_id:
            mem = m
            break
    if not mem:
        # Log under any active client context if possible
        any_active = next((c for c in api_clients if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("id"), str)), None)
        if any_active:
            _log(invocations, any_active["id"], "failed", {"memory_id": memory_id}, response_summary={"error_code": "NOT_FOUND"}, error_message="Memory not found.", related_memory_id=memory_id, started=started)
        return _err("NOT_FOUND", "Memory not found.")

    owner_client_id = mem.get("client_id")
    owner_client = None
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == owner_client_id:
            owner_client = c
            break
    if not owner_client or owner_client.get("status") != "active":
        any_active = next((c for c in api_clients if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("id"), str)), None)
        cid_for_log = any_active["id"] if any_active else (owner_client_id if isinstance(owner_client_id, str) else "unknown")
        _log(invocations, cid_for_log, "failed", {"memory_id": memory_id}, response_summary={"error_code": "UNAUTHORIZED"}, error_message="Memory is not visible to the caller.", related_memory_id=memory_id, started=started)
        return _err("UNAUTHORIZED", "Memory is not visible to the caller.")

    # Rate limit for owner client
    rpm = owner_client.get("quota_requests_per_minute")
    if not isinstance(rpm, int) or rpm < 0 or rpm == 0:
        _log(invocations, owner_client_id, "failed", {"memory_id": memory_id}, response_summary={"error_code": "RATE_LIMIT"}, error_message="Rate limit exceeded.", related_memory_id=memory_id, started=started)
        return _err("RATE_LIMIT", "Rate limit exceeded.")
    now_dt = _utcnow()
    cutoff = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for inv in invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("client_id") != owner_client_id:
            continue
        t = _parse_iso(inv.get("created_at"))
        if t is None:
            continue
        if t >= cutoff:
            recent += 1
    if recent >= rpm:
        _log(invocations, owner_client_id, "failed", {"memory_id": memory_id}, response_summary={"error_code": "RATE_LIMIT"}, error_message="Rate limit exceeded.", related_memory_id=memory_id, started=started)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    if mem.get("status") == "deleted":
        _log(invocations, owner_client_id, "failed", {"memory_id": memory_id}, response_summary={"error_code": "CONFLICT"}, error_message="Memory is already deleted.", related_memory_id=memory_id, started=started)
        return _err("CONFLICT", "Memory is already deleted.")

    # Mutate
    now_iso = _now_iso()
    mem["status"] = "deleted"
    mem["deleted_at"] = now_iso
    mem["updated_at"] = now_iso

    # Append version snapshot
    maxv = 0
    for v in versions:
        if not isinstance(v, dict):
            continue
        if v.get("memory_id") == memory_id:
            vv = v.get("version")
            if isinstance(vv, int) and vv > maxv:
                maxv = vv
    next_version = maxv + 1 if maxv >= 1 else 1

    inv_id = _log(invocations, owner_client_id, "succeeded", {"memory_id": memory_id}, response_summary={"memory_id": memory_id}, related_memory_id=memory_id, started=started)
    mver_id = "memc_mver_" + secrets.token_hex(13)
    versions.append({
        "id": mver_id,
        "memory_id": memory_id,
        "version": next_version,
        "title": mem.get("title"),
        "content": mem.get("content"),
        "content_sha256": mem.get("content_sha256"),
        "change_type": "delete",
        "created_by_invocation_id": inv_id,
        "created_at": now_iso,
        "updated_at": now_iso
    })

    owner_client["last_seen_at"] = now_iso
    owner_client["updated_at"] = owner_client.get("updated_at") or now_iso

    _save("memories.json", memories)
    _save("memory_versions.json", versions)
    _save("api_clients.json", api_clients)

    return {"memory": mem}

def list_tool_invocations(limit=None, cursor=None, status=None, tool_name=None, related_memory_id=None, since=None, until=None, order=None, include_request_params=None, include_response_summary=None, include_error_message=None, **_extra):
    import json, os, datetime, time, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0262000" if __import__("os").path.isdir("./environment_mix/0262000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _utcnow().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict):
                return obj
        except Exception:
            return None
        return None

    def _pick_client(api_clients):
        active = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None
        def key(c):
            q = c.get("quota_requests_per_minute")
            return (q if isinstance(q, int) else 0)
        return sorted(active, key=key, reverse=True)[0]

    def _rate_limit_check(client_row, invocations):
        qrpm = client_row.get("quota_requests_per_minute")
        if not isinstance(qrpm, int) or qrpm < 0:
            qrpm = 0
        if qrpm == 0:
            return True, None
        now = _utcnow()
        window_start = now - datetime.timedelta(minutes=1)
        cnt = 0
        cid = client_row.get("id")
        for inv in invocations:
            if not isinstance(inv, dict):
                continue
            if inv.get("client_id") != cid:
                continue
            ts = _parse_iso(inv.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        if cnt >= qrpm:
            return False, _err("RATE_LIMIT", "Rate limit exceeded.")
        return True, None

    def _log(invocations, client_id, status_str, request_params, response_summary=None, error_message=None, started=None):
        now_iso = _now_iso()
        dur = 0
        if started is not None:
            dur = max(0, int((time.time() - started) * 1000))
        inv_id = "memc_inv_" + secrets.token_hex(13)
        invocations.append({
            "id": inv_id,
            "client_id": client_id,
            "tool_name": "list_tool_invocations",
            "status": status_str,
            "request_params": request_params,
            "response_summary": response_summary,
            "error_message": error_message,
            "related_memory_id": None,
            "duration_ms": dur,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_invocations.json", invocations)
        return inv_id

    started = time.time()
    api_clients = _load("api_clients.json")
    invocations = _load("tool_invocations.json")

    client = _pick_client(api_clients)
    if not client or not client.get("id"):
        return _err("UNAUTHORIZED", "No authorized client context available.")
    client_id = client["id"]

    ok, rl_err = _rate_limit_check(client, invocations)
    if not ok:
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name, "related_memory_id": related_memory_id, "since": since, "until": until, "order": order, "include_request_params": include_request_params, "include_response_summary": include_response_summary, "include_error_message": include_error_message}, response_summary={"error_code": rl_err["error"]["code"]}, error_message=rl_err["error"]["message"], started=started)
        return rl_err

    # Update last_seen_at
    now_iso = _now_iso()
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_seen_at"] = now_iso
            c["updated_at"] = now_iso if isinstance(c.get("updated_at"), str) else now_iso
            _save("api_clients.json", api_clients)
            break

    # Validation
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name, "related_memory_id": related_memory_id, "since": since, "until": until, "order": order, "include_request_params": include_request_params, "include_response_summary": include_response_summary, "include_error_message": include_error_message}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="limit must be an integer.", started=started)
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 100:
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name, "related_memory_id": related_memory_id, "since": since, "until": until, "order": order, "include_request_params": include_request_params, "include_response_summary": include_response_summary, "include_error_message": include_error_message}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="limit must be between 1 and 100.", started=started)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
    if status is not None:
        if not isinstance(status, str) or status not in ("succeeded", "failed"):
            _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name, "related_memory_id": related_memory_id, "since": since, "until": until, "order": order, "include_request_params": include_request_params, "include_response_summary": include_response_summary, "include_error_message": include_error_message}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="Invalid status.", started=started)
            return _err("VALIDATION_ERROR", "Invalid status.")
    if tool_name is not None and not isinstance(tool_name, str):
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name, "related_memory_id": related_memory_id, "since": since, "until": until, "order": order, "include_request_params": include_request_params, "include_response_summary": include_response_summary, "include_error_message": include_error_message}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="tool_name must be a string.", started=started)
        return _err("VALIDATION_ERROR", "tool_name must be a string.")
    if related_memory_id is not None and not isinstance(related_memory_id, int):
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name, "related_memory_id": related_memory_id, "since": since, "until": until, "order": order, "include_request_params": include_request_params, "include_response_summary": include_response_summary, "include_error_message": include_error_message}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="related_memory_id must be an integer.", started=started)
        return _err("VALIDATION_ERROR", "related_memory_id must be an integer.")
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name, "related_memory_id": related_memory_id, "since": since, "until": until, "order": order, "include_request_params": include_request_params, "include_response_summary": include_response_summary, "include_error_message": include_error_message}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="Invalid order.", started=started)
        return _err("VALIDATION_ERROR", "Invalid order.")
    since_dt = _parse_iso(since) if since is not None else None
    if since is not None and since_dt is None:
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name, "related_memory_id": related_memory_id, "since": since, "until": until, "order": order, "include_request_params": include_request_params, "include_response_summary": include_response_summary, "include_error_message": include_error_message}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="Invalid since timestamp.", started=started)
        return _err("VALIDATION_ERROR", "Invalid since timestamp.")
    until_dt = _parse_iso(until) if until is not None else None
    if until is not None and until_dt is None:
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name, "related_memory_id": related_memory_id, "since": since, "until": until, "order": order, "include_request_params": include_request_params, "include_response_summary": include_response_summary, "include_error_message": include_error_message}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="Invalid until timestamp.", started=started)
        return _err("VALIDATION_ERROR", "Invalid until timestamp.")
    if since_dt and until_dt and since_dt > until_dt:
        _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name, "related_memory_id": related_memory_id, "since": since, "until": until, "order": order, "include_request_params": include_request_params, "include_response_summary": include_response_summary, "include_error_message": include_error_message}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="since must be <= until.", started=started)
        return _err("VALIDATION_ERROR", "since must be <= until.")
    for bname, bval in (("include_request_params", include_request_params), ("include_response_summary", include_response_summary), ("include_error_message", include_error_message)):
        if bval is not None and not isinstance(bval, bool):
            _log(invocations, client_id, "failed", {"limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name, "related_memory_id": related_memory_id, "since": since, "until": until, "order": order, "include_request_params": include_request_params, "include_response_summary": include_response_summary, "include_error_message": include_error_message}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message=f"{bname} must be a boolean.", started=started)
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean.")

    cur = _decode_cursor(cursor)
    if cursor is not None and cursor != "" and cur is None:
        # Relax invalid cursors (audit used client_id) as "no cursor"
        cur = None
    offset = 0
    if isinstance(cur, dict):
        off = cur.get("offset")
        if isinstance(off, int) and off >= 0:
            offset = off

    # Filter rows scoped to client_id
    rows = []
    for inv in invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("client_id") != client_id:
            continue
        if status is not None and inv.get("status") != status:
            continue
        if tool_name is not None and inv.get("tool_name") != tool_name:
            continue
        if related_memory_id is not None and inv.get("related_memory_id") != related_memory_id:
            continue
        created_dt = _parse_iso(inv.get("created_at"))
        if since_dt is not None:
            if created_dt is None or created_dt < since_dt:
                continue
        if until_dt is not None:
            if created_dt is None or created_dt > until_dt:
                continue
        rows.append(inv)

    # Sort by created_at
    reverse = (order == "desc")
    def _sort_key(r):
        dt = _parse_iso(r.get("created_at"))
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
    rows_sorted = sorted(rows, key=_sort_key, reverse=reverse)

    total = len(rows_sorted)
    page = rows_sorted[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = _encode_cursor({"offset": offset + limit}) if has_more else None

    # Redaction toggles
    inc_req = (include_request_params is True)
    inc_resp = (include_response_summary is True)
    inc_err = (include_error_message is True)

    out = []
    for r in page:
        rr = dict(r)
        if not inc_req:
            rr.pop("request_params", None)
        if not inc_resp:
            rr.pop("response_summary", None)
        if not inc_err:
            rr.pop("error_message", None)
        out.append(rr)

    resp = {"invocations": out, "total": total, "has_more": has_more, "next_cursor": next_cursor}
    _log(invocations, client_id, "succeeded", {"limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name, "related_memory_id": related_memory_id, "since": since, "until": until, "order": order, "include_request_params": include_request_params, "include_response_summary": include_response_summary, "include_error_message": include_error_message}, response_summary={"returned": len(out), "total": total, "has_more": has_more}, started=started)
    return resp

def get_tool_invocation(invocation_id, include_request_params=None, include_response_summary=None, include_error_message=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0262000" if __import__("os").path.isdir("./environment_mix/0262000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _utcnow().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _gen_inv_id():
        return "memc_inv_" + secrets.token_hex(13)

    def _log(invocations, client_id, tool_name, status_str, request_params, response_summary=None, error_message=None, started=None):
        now_iso = _now_iso()
        dur = 0
        if started is not None:
            dur = max(0, int((time.time() - started) * 1000))
        row = {
            "id": _gen_inv_id(),
            "client_id": client_id,
            "tool_name": tool_name,
            "status": status_str,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_summary": response_summary,
            "error_message": error_message,
            "related_memory_id": None,
            "duration_ms": dur,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return row["id"]

    def _rate_limit_check(client_row, invocations):
        qrpm = client_row.get("quota_requests_per_minute")
        if not isinstance(qrpm, int) or qrpm < 0:
            qrpm = 0
        if qrpm == 0:
            return True, None
        now = _utcnow()
        window_start = now - datetime.timedelta(minutes=1)
        cid = client_row.get("id")
        cnt = 0
        for inv in invocations:
            if not isinstance(inv, dict):
                continue
            if inv.get("client_id") != cid:
                continue
            ts = _parse_iso(inv.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        if cnt >= qrpm:
            return False, _err("RATE_LIMIT", "Rate limit exceeded.")
        return True, None

    def _pick_client(api_clients, invocations):
        candidates = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("id"), str)]
        if not candidates:
            return None
        viable = []
        for c in candidates:
            ok, _ = _rate_limit_check(c, invocations)
            if ok:
                qrpm = c.get("quota_requests_per_minute")
                qrpm = qrpm if isinstance(qrpm, int) and qrpm >= 0 else 0
                viable.append((qrpm, c))
        if viable:
            viable.sort(key=lambda t: t[0], reverse=True)
            return viable[0][1]
        return None

    def _normalize_bool(x):
        if x is None:
            return False
        if isinstance(x, bool):
            return x
        return False

    started = time.time()
    api_clients = _load("api_clients.json")
    invocations = _load("tool_invocations.json")

    client = _pick_client(api_clients, invocations)
    if client is None:
        fallback = next((c for c in api_clients if isinstance(c, dict) and isinstance(c.get("id"), str)), None)
        if fallback is not None:
            _log(invocations, fallback.get("id"), "get_tool_invocation", "failed",
                 {"invocation_id": invocation_id,
                  "include_request_params": include_request_params,
                  "include_response_summary": include_response_summary,
                  "include_error_message": include_error_message},
                 response_summary={"error": {"code": "UNAUTHORIZED"}},
                 error_message="No authorized client context available.", started=started)
        return _err("UNAUTHORIZED", "No authorized client context available.")

    ok, rl_err = _rate_limit_check(client, invocations)
    if not ok:
        _log(invocations, client["id"], "get_tool_invocation", "failed",
             {"invocation_id": invocation_id,
              "include_request_params": include_request_params,
              "include_response_summary": include_response_summary,
              "include_error_message": include_error_message},
             response_summary={"error": rl_err["error"]},
             error_message=rl_err["error"]["message"], started=started)
        return rl_err

    # Validation: real ids are strings like memc_inv_..., but audit used integer; accept int as index fallback.
    if invocation_id is None or not (isinstance(invocation_id, int) or (isinstance(invocation_id, str) and invocation_id.strip() != "")):
        _log(invocations, client["id"], "get_tool_invocation", "failed",
             {"invocation_id": invocation_id,
              "include_request_params": include_request_params,
              "include_response_summary": include_response_summary,
              "include_error_message": include_error_message},
             response_summary={"error": {"code": "VALIDATION_ERROR"}},
             error_message="invocation_id must be an integer or non-empty string.", started=started)
        return _err("VALIDATION_ERROR", "invocation_id must be an integer or non-empty string.")

    cid = client["id"]
    row = None

    if isinstance(invocation_id, str):
        for inv in invocations:
            if isinstance(inv, dict) and inv.get("id") == invocation_id and inv.get("client_id") == cid:
                row = inv
                break
    else:
        # integer: treat as 1-based index within this client's invocations ordered by created_at asc (stable)
        client_invs = [inv for inv in invocations if isinstance(inv, dict) and inv.get("client_id") == cid]
        client_invs.sort(key=lambda r: (_parse_iso(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), str(r.get("id"))))
        idx = invocation_id - 1
        if 0 <= idx < len(client_invs):
            row = client_invs[idx]

    if row is None:
        _log(invocations, cid, "get_tool_invocation", "failed",
             {"invocation_id": invocation_id,
              "include_request_params": include_request_params,
              "include_response_summary": include_response_summary,
              "include_error_message": include_error_message},
             response_summary={"error": {"code": "NOT_FOUND"}},
             error_message="Tool invocation not found.", started=started)
        return _err("NOT_FOUND", "Tool invocation not found.")

    # Update last_seen_at
    now_iso = _now_iso()
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == cid:
            c["last_seen_at"] = now_iso
            c["updated_at"] = c.get("updated_at") or now_iso
            _save("api_clients.json", api_clients)
            break

    inc_req = _normalize_bool(include_request_params)
    inc_resp = _normalize_bool(include_response_summary)
    inc_err = _normalize_bool(include_error_message)

    result = {
        "id": row.get("id"),
        "client_id": row.get("client_id"),
        "tool_name": row.get("tool_name"),
        "status": row.get("status"),
        "related_memory_id": row.get("related_memory_id"),
        "duration_ms": row.get("duration_ms"),
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
    }
    if inc_req:
        result["request_params"] = row.get("request_params")
    if inc_resp:
        result["response_summary"] = row.get("response_summary")
    if inc_err:
        result["error_message"] = row.get("error_message")

    _log(invocations, cid, "get_tool_invocation", "succeeded",
         {"invocation_id": invocation_id,
          "include_request_params": include_request_params,
          "include_response_summary": include_response_summary,
          "include_error_message": include_error_message},
         response_summary={"tool_invocation_id": row.get("id")}, started=started)

    return {"tool_invocation": result}

def list_memory_versions(memory_id=None, limit=None, cursor=None, change_type=None, min_version=None, max_version=None, order=None, include_content=None, **_extra):
    import json, os, datetime, time, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0262000" if __import__("os").path.isdir("./environment_mix/0262000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _utcnow().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict):
                return obj
        except Exception:
            return None
        return None

    def _pick_client(api_clients):
        active = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None
        def key(c):
            q = c.get("quota_requests_per_minute")
            return (q if isinstance(q, int) else 0)
        return sorted(active, key=key, reverse=True)[0]

    def _rate_limit_check(client_row, invocations):
        qrpm = client_row.get("quota_requests_per_minute")
        if not isinstance(qrpm, int) or qrpm < 0:
            qrpm = 0
        if qrpm == 0:
            return True, None
        now = _utcnow()
        window_start = now - datetime.timedelta(minutes=1)
        cnt = 0
        cid = client_row.get("id")
        for inv in invocations:
            if not isinstance(inv, dict):
                continue
            if inv.get("client_id") != cid:
                continue
            ts = _parse_iso(inv.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        if cnt >= qrpm:
            return False, _err("RATE_LIMIT", "Rate limit exceeded.")
        return True, None

    def _log(invocations, client_id, status_str, request_params, response_summary=None, error_message=None, started=None):
        now_iso = _now_iso()
        dur = 0
        if started is not None:
            dur = max(0, int((time.time() - started) * 1000))
        inv_id = "memc_inv_" + secrets.token_hex(13)
        invocations.append({
            "id": inv_id,
            "client_id": client_id,
            "tool_name": "list_memory_versions",
            "status": status_str,
            "request_params": request_params,
            "response_summary": response_summary,
            "error_message": error_message,
            "related_memory_id": memory_id if isinstance(memory_id, int) else None,
            "duration_ms": dur,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_invocations.json", invocations)
        return inv_id

    started = time.time()
    api_clients = _load("api_clients.json")
    memories = _load("memories.json")
    versions = _load("memory_versions.json")
    invocations = _load("tool_invocations.json")

    client = _pick_client(api_clients)
    if not client or not client.get("id"):
        return _err("UNAUTHORIZED", "No authorized client context available.")
    client_id = client["id"]

    ok, rl_err = _rate_limit_check(client, invocations)
    if not ok:
        _log(invocations, client_id, "failed", {"memory_id": memory_id, "limit": limit, "cursor": cursor, "change_type": change_type, "min_version": min_version, "max_version": max_version, "order": order, "include_content": include_content}, response_summary={"error_code": rl_err["error"]["code"]}, error_message=rl_err["error"]["message"], started=started)
        return rl_err

    # Update last_seen_at
    now_iso = _now_iso()
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_seen_at"] = now_iso
            c["updated_at"] = now_iso if isinstance(c.get("updated_at"), str) else now_iso
            _save("api_clients.json", api_clients)
            break

    # Validation
    if memory_id is not None and not isinstance(memory_id, int):
        _log(invocations, client_id, "failed", {"memory_id": memory_id, "limit": limit, "cursor": cursor, "change_type": change_type, "min_version": min_version, "max_version": max_version, "order": order, "include_content": include_content}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="memory_id must be an integer.", started=started)
        return _err("VALIDATION_ERROR", "memory_id must be an integer.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log(invocations, client_id, "failed", {"memory_id": memory_id, "limit": limit, "cursor": cursor, "change_type": change_type, "min_version": min_version, "max_version": max_version, "order": order, "include_content": include_content}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="limit must be an integer.", started=started)
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 100:
        _log(invocations, client_id, "failed", {"memory_id": memory_id, "limit": limit, "cursor": cursor, "change_type": change_type, "min_version": min_version, "max_version": max_version, "order": order, "include_content": include_content}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="limit must be between 1 and 100.", started=started)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
    if change_type is not None:
        if not isinstance(change_type, str) or change_type not in ("create", "update", "delete"):
            _log(invocations, client_id, "failed", {"memory_id": memory_id, "limit": limit, "cursor": cursor, "change_type": change_type, "min_version": min_version, "max_version": max_version, "order": order, "include_content": include_content}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="Invalid change_type.", started=started)
            return _err("VALIDATION_ERROR", "Invalid change_type.")
    if min_version is not None and (not isinstance(min_version, int) or min_version < 1):
        _log(invocations, client_id, "failed", {"memory_id": memory_id, "limit": limit, "cursor": cursor, "change_type": change_type, "min_version": min_version, "max_version": max_version, "order": order, "include_content": include_content}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="min_version must be an integer >= 1.", started=started)
        return _err("VALIDATION_ERROR", "min_version must be an integer >= 1.")
    if max_version is not None and (not isinstance(max_version, int) or max_version < 1):
        _log(invocations, client_id, "failed", {"memory_id": memory_id, "limit": limit, "cursor": cursor, "change_type": change_type, "min_version": min_version, "max_version": max_version, "order": order, "include_content": include_content}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="max_version must be an integer >= 1.", started=started)
        return _err("VALIDATION_ERROR", "max_version must be an integer >= 1.")
    if min_version is not None and max_version is not None and min_version > max_version:
        _log(invocations, client_id, "failed", {"memory_id": memory_id, "limit": limit, "cursor": cursor, "change_type": change_type, "min_version": min_version, "max_version": max_version, "order": order, "include_content": include_content}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="min_version must be <= max_version.", started=started)
        return _err("VALIDATION_ERROR", "min_version must be <= max_version.")
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log(invocations, client_id, "failed", {"memory_id": memory_id, "limit": limit, "cursor": cursor, "change_type": change_type, "min_version": min_version, "max_version": max_version, "order": order, "include_content": include_content}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="Invalid order.", started=started)
        return _err("VALIDATION_ERROR", "Invalid order.")
    if include_content is not None and not isinstance(include_content, bool):
        _log(invocations, client_id, "failed", {"memory_id": memory_id, "limit": limit, "cursor": cursor, "change_type": change_type, "min_version": min_version, "max_version": max_version, "order": order, "include_content": include_content}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="include_content must be a boolean.", started=started)
        return _err("VALIDATION_ERROR", "include_content must be a boolean.")

    # Resolve visible memory ids for client
    visible_memory_ids = set()
    for m in memories:
        if isinstance(m, dict) and m.get("client_id") == client_id:
            mid = m.get("id")
            if isinstance(mid, int):
                visible_memory_ids.add(mid)

    if memory_id is not None:
        if memory_id not in visible_memory_ids:
            # No versions visible if memory isn't visible; return empty set (read tools return empty, not error)
            resp = {"versions": [], "total": 0, "has_more": False, "next_cursor": None}
            _log(invocations, client_id, "succeeded", {"memory_id": memory_id, "limit": limit, "cursor": cursor, "change_type": change_type, "min_version": min_version, "max_version": max_version, "order": order, "include_content": include_content}, response_summary={"returned": 0, "total": 0, "has_more": False}, started=started)
            return resp

    cur = _decode_cursor(cursor)
    if cursor is not None and cursor != "" and cur is None:
        cur = None
    offset = 0
    if isinstance(cur, dict):
        off = cur.get("offset")
        if isinstance(off, int) and off >= 0:
            offset = off

    # Filter versions
    rows = []
    for v in versions:
        if not isinstance(v, dict):
            continue
        mid = v.get("memory_id")
        if not isinstance(mid, int):
            continue
        if mid not in visible_memory_ids:
            continue
        if memory_id is not None and mid != memory_id:
            continue
        if change_type is not None and v.get("change_type") != change_type:
            continue
        vernum = v.get("version")
        if not isinstance(vernum, int):
            continue
        if min_version is not None and vernum < min_version:
            continue
        if max_version is not None and vernum > max_version:
            continue
        rows.append(v)

    # Sort
    reverse = (order == "desc")
    if memory_id is not None:
        rows_sorted = sorted(rows, key=lambda r: (r.get("version") if isinstance(r.get("version"), int) else 0), reverse=reverse)
    else:
        def _k(r):
            dt = _parse_iso(r.get("created_at"))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        rows_sorted = sorted(rows, key=_k, reverse=reverse)

    total = len(rows_sorted)
    page = rows_sorted[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = _encode_cursor({"offset": offset + limit}) if has_more else None

    inc = (include_content is True)
    out = []
    for r in page:
        rr = dict(r)
        if not inc:
            rr.pop("title", None)
            rr.pop("content", None)
        out.append(rr)

    resp = {"versions": out, "total": total, "has_more": has_more, "next_cursor": next_cursor}
    _log(invocations, client_id, "succeeded", {"memory_id": memory_id, "limit": limit, "cursor": cursor, "change_type": change_type, "min_version": min_version, "max_version": max_version, "order": order, "include_content": include_content}, response_summary={"returned": len(out), "total": total, "has_more": has_more}, started=started)
    return resp

