        return None

    def _rate_limit_check(client_row, invocations):
        qrpm = client_row.get("quota_requests_per_minute")
        if not isinstance(qrpm, int) or qrpm < 0:
            qrpm = 0
        if qrpm == 0:
            return True, None
        now = _utcnow()
        window_start = now - datetime.timedelta(minutes=1)
        cnt = 0
        cid = client_row.get("id")
        for inv in invocations:
            if not isinstance(inv, dict):
                continue
            if inv.get("client_id") != cid:
                continue
            ts = _parse_iso(inv.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        if cnt >= qrpm:
            return False, _err("RATE_LIMIT", "Rate limit exceeded.")
        return True, None

    def _log(invocations, client_id, tool_name, status_str, request_params, response_summary=None, error_message=None, related_memory_id=None, started=None):
        now_iso = _now_iso()
        dur = 0
        if started is not None:
            dur = max(0, int((time.time() - started) * 1000))
        row = {
            "id": _gen_inv_id(),
            "client_id": client_id,
            "tool_name": tool_name,
            "status": status_str,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_summary": response_summary,
            "error_message": error_message,
            "related_memory_id": related_memory_id,
            "duration_ms": dur,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return row["id"]

    started = time.time()
    api_clients = _load("api_clients.json")
    memories = _load("memories.json")
    versions = _load("memory_versions.json")
    invocations = _load("tool_invocations.json")

    if not isinstance(api_clients, list) or not isinstance(memories, list) or not isinstance(versions, list) or not isinstance(invocations, list):
        return _err("NOT_FOUND", "Datastore unavailable.")

    # Validation
    if not isinstance(memory_version_id, int):
        e = _err("VALIDATION_ERROR", "memory_version_id must be an integer.")
        # best-effort logging with ambient client selection
        cid = _choose_client(api_clients, memories)
        if cid is not None:
            _log(invocations, cid, "get_memory_version", "failed", {"memory_version_id": memory_version_id, "include_content": include_content}, response_summary={"error_code": e["error"]["code"]}, error_message=e["error"]["message"], started=started)
        return e
    if include_content is not None and not isinstance(include_content, bool):
        e = _err("VALIDATION_ERROR", "include_content must be a boolean.")
        cid = _choose_client(api_clients, memories)
        if cid is not None:
            _log(invocations, cid, "get_memory_version", "failed", {"memory_version_id": memory_version_id, "include_content": include_content}, response_summary={"error_code": e["error"]["code"]}, error_message=e["error"]["message"], started=started)
        return e

    client_id = _choose_client(api_clients, memories)
    if client_id is None:
        return _err("UNAUTHORIZED", "No authorized client context available.")
    client_row = next((c for c in api_clients if isinstance(c, dict) and c.get("id") == client_id), None)
    if client_row is None:
        return _err("UNAUTHORIZED", "No authorized client context available.")

    ok, rl_err = _rate_limit_check(client_row, invocations)
    if not ok:
        _log(invocations, client_id, "get_memory_version", "failed", {"memory_version_id": memory_version_id, "include_content": include_content}, response_summary={"error_code": rl_err["error"]["code"]}, error_message=rl_err["error"]["message"], started=started)
        return rl_err

    # Update last_seen_at for observed dynamics
    now_iso = _now_iso()
    client_row["last_seen_at"] = now_iso
    client_row["updated_at"] = now_iso
    _save("api_clients.json", api_clients)

    # Find version row. NOTE: datastore has string ids, but tool takes integer; accept both:
    target = None
    for v in versions:
        if not isinstance(v, dict):
            continue
        vid = v.get("id")
        if vid == memory_version_id or (isinstance(vid, str) and vid.strip() == str(memory_version_id)):
            target = v
            break
        if isinstance(vid, str):
            # Also accept numeric suffix match, e.g. "..._5"
            parts = vid.split("_")
            if parts and parts[-1].isdigit() and int(parts[-1]) == memory_version_id:
                target = v
                break

    if target is None:
        e = _err("NOT_FOUND", "Memory version not found.")
        _log(invocations, client_id, "get_memory_version", "failed", {"memory_version_id": memory_version_id, "include_content": include_content}, response_summary={"error_code": e["error"]["code"]}, error_message=e["error"]["message"], started=started)
        return e

    mem_id = target.get("memory_id")
    mem_row = None
    for m in memories:
        if isinstance(m, dict) and m.get("id") == mem_id:
            mem_row = m
            break

    # Scope visibility by underlying memory's client_id
    if mem_row is None or mem_row.get("client_id") != client_id:
        e = _err("NOT_FOUND", "Memory version not found.")
        _log(invocations, client_id, "get_memory_version", "failed", {"memory_version_id": memory_version_id, "include_content": include_content}, response_summary={"error_code": e["error"]["code"]}, error_message=e["error"]["message"], started=started)
        return e

    # Shape response
    include = True if include_content is True else False
    out = {
        "id": target.get("id"),
        "memory_id": target.get("memory_id"),
        "version": target.get("version"),
        "content_sha256": target.get("content_sha256"),
        "change_type": target.get("change_type"),
        "created_by_invocation_id": target.get("created_by_invocation_id"),
        "created_at": target.get("created_at"),
        "updated_at": target.get("updated_at"),
    }
    if include:
        out["title"] = target.get("title")
        out["content"] = target.get("content")

    _log(invocations, client_id, "get_memory_version", "succeeded", {"memory_version_id": memory_version_id, "include_content": include_content}, response_summary={"memory_version_id": target.get("id"), "memory_id": mem_id}, related_memory_id=mem_id, started=started)
    return {"memory_version": out}

def restore_memory(memory_id, on_title_conflict=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0262000" if __import__("os").path.isdir("./environment_mix/0262000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _utcnow().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _log(invocations, client_id, status, request_params, response_summary=None, error_message=None, related_memory_id=None, started=None):
        inv_id = "memc_inv_" + secrets.token_hex(13)
        now_iso = _now_iso()
        dur = 0
        if started is not None:
            dur = max(0, int((time.time() - started) * 1000))
        invocations.append({
            "id": inv_id,
            "client_id": client_id,
            "tool_name": "restore_memory",
            "status": status,
            "request_params": request_params,
            "response_summary": response_summary,
            "error_message": error_message,
            "related_memory_id": related_memory_id,
            "duration_ms": dur,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_invocations.json", invocations)
        return inv_id

    started = time.time()
    api_clients = _load("api_clients.json")
    memories = _load("memories.json")
    versions = _load("memory_versions.json")
    invocations = _load("tool_invocations.json")

    if on_title_conflict is None:
        on_title_conflict = "fail"

    # Validate
    any_active_client = next((c for c in api_clients if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("id"), str)), None)
    log_client_id = any_active_client["id"] if any_active_client else None

    if not isinstance(memory_id, int):
        if log_client_id:
            _log(invocations, log_client_id, "failed", {"memory_id": memory_id, "on_title_conflict": on_title_conflict}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="memory_id must be an integer.", started=started)
        return _err("VALIDATION_ERROR", "memory_id must be an integer.")
    if on_title_conflict not in ("fail",):
        if log_client_id:
            _log(invocations, log_client_id, "failed", {"memory_id": memory_id, "on_title_conflict": on_title_conflict}, response_summary={"error_code": "VALIDATION_ERROR"}, error_message="Invalid on_title_conflict.", related_memory_id=memory_id, started=started)
        return _err("VALIDATION_ERROR", "Invalid on_title_conflict.")

    # Find memory by id (regardless of chosen ambient client)
    mem = None
    for m in memories:
        if isinstance(m, dict) and m.get("id") == memory_id:
            mem = m
            break
    if not mem:
        if log_client_id:
            _log(invocations, log_client_id, "failed", {"memory_id": memory_id, "on_title_conflict": on_title_conflict}, response_summary={"error_code": "NOT_FOUND"}, error_message="Memory not found.", related_memory_id=memory_id, started=started)
        return _err("NOT_FOUND", "Memory not found.")

    owner_client_id = mem.get("client_id")
    owner_client = None
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == owner_client_id:
            owner_client = c
            break
    if not owner_client or owner_client.get("status") != "active":
        cid_for_log = log_client_id or (owner_client_id if isinstance(owner_client_id, str) else "unknown")
        _log(invocations, cid_for_log, "failed", {"memory_id": memory_id, "on_title_conflict": on_title_conflict}, response_summary={"error_code": "UNAUTHORIZED"}, error_message="Memory is not visible to the caller.", related_memory_id=memory_id, started=started)
        return _err("UNAUTHORIZED", "Memory is not visible to the caller.")

    # Rate limit for owner
    rpm = owner_client.get("quota_requests_per_minute")
    if not isinstance(rpm, int) or rpm < 0 or rpm == 0:
        _log(invocations, owner_client_id, "failed", {"memory_id": memory_id, "on_title_conflict": on_title_conflict}, response_summary={"error_code": "RATE_LIMIT"}, error_message="Rate limit exceeded.", related_memory_id=memory_id, started=started)
        return _err("RATE_LIMIT", "Rate limit exceeded.")
    now_dt = _utcnow()
    cutoff = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for inv in invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("client_id") != owner_client_id:
            continue
        t = _parse_iso(inv.get("created_at"))
        if t is None:
            continue
        if t >= cutoff:
            recent += 1
    if recent >= rpm:
        _log(invocations, owner_client_id, "failed", {"memory_id": memory_id, "on_title_conflict": on_title_conflict}, response_summary={"error_code": "RATE_LIMIT"}, error_message="Rate limit exceeded.", related_memory_id=memory_id, started=started)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Must be deleted to restore
    if mem.get("status") != "deleted":
        _log(invocations, owner_client_id, "failed", {"memory_id": memory_id, "on_title_conflict": on_title_conflict}, response_summary={"error_code": "CONFLICT"}, error_message="Memory is not deleted and cannot be restored.", related_memory_id=memory_id, started=started)
        return _err("CONFLICT", "Memory is not deleted and cannot be restored.")

    # Unique active title per client constraint on restore
    mem_title = mem.get("title")
    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("id") == memory_id:
            continue
        if m.get("client_id") != owner_client_id:
            continue
        if m.get("status") != "active":
            continue
        if m.get("title") == mem_title:
            _log(invocations, owner_client_id, "failed", {"memory_id": memory_id, "on_title_conflict": on_title_conflict}, response_summary={"error_code": "CONFLICT"}, error_message="Cannot restore: an active memory with the same title already exists.", related_memory_id=memory_id, started=started)
            return _err("CONFLICT", "Cannot restore: an active memory with the same title already exists.")

    # Restore
    now_iso = _now_iso()
    mem["status"] = "active"
    mem["deleted_at"] = None
    mem["updated_at"] = now_iso

    # Append version row (change_type='update' fits transitions; there's no 'restore' enum)
    maxv = 0
    for v in versions:
        if isinstance(v, dict) and v.get("memory_id") == memory_id and isinstance(v.get("version"), int):
            if v["version"] > maxv:
                maxv = v["version"]
    next_version = maxv + 1 if maxv >= 1 else 1

    inv_id = _log(invocations, owner_client_id, "succeeded", {"memory_id": memory_id, "on_title_conflict": on_title_conflict}, response_summary={"memory_id": memory_id}, related_memory_id=memory_id, started=started)
    versions.append({
        "id": "memc_mver_" + secrets.token_hex(13),
        "memory_id": memory_id,
        "version": next_version,
        "title": mem.get("title"),
        "content": mem.get("content"),
        "content_sha256": mem.get("content_sha256"),
        "change_type": "update",
        "created_by_invocation_id": inv_id,
        "created_at": now_iso,
        "updated_at": now_iso
    })

    owner_client["last_seen_at"] = now_iso
    owner_client["updated_at"] = owner_client.get("updated_at") or now_iso

    _save("memories.json", memories)
    _save("memory_versions.json", versions)
    _save("api_clients.json", api_clients)

    return {"memory": mem}
